INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','countable-uncountable','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"countable-uncountable","title":"Countable and uncountable nouns","level":"A1","order":14,"summary":"Choose quantity expressions and agreement from a noun’s meaning in context.","learningGoals":["Count the things or measure an amount","Asking about quantity","Some and individual units"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Count the things or measure an amount","explanation":"Countable nouns name separate units and can be plural. Uncountable nouns name amounts or collections in the senses used here. Other senses may differ.","examples":["three baskets","some equipment"]},{"title":"Asking about quantity","explanation":"Use how many before plural countable nouns and how much before uncountable nouns. Use plural agreement with the former and singular agreement with the latter.","examples":["How many baskets are ready?","How much equipment is available?"]},{"title":"Some and individual units","explanation":"Some works with both plural countable and uncountable nouns. For an uncountable noun, add a unit phrase when counting individual quantities.","examples":["some luggage","two pieces of luggage"]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-countable-uncountable"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"0d4628ca-a9a8-578f-acf0-25e78f828450","topicSlug":"countable-uncountable","level":"A1","prompt":"For collecting postage stamps, how is “stamps” used?","choices":[{"id":"A","text":"An adjective"},{"id":"B","text":"A plural countable noun"},{"id":"C","text":"An uncountable noun"},{"id":"D","text":"A singular countable noun"}],"answerId":"B","hint":"Countable nouns name separate units and can be plural. Uncountable nouns name amounts or collections in the senses used here. Other senses may differ. Focus on **countability** in this question.","explanation":"Stamps are used for separate countable units here. This classification applies to the stated sense.","keywords":[],"source":"seed","skill":"countability","contextKey":"quantity-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-countable-uncountable"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"10199f2c7b34e019e8ce5abc342958b09357ee3515f5af30c5bd4e93abfd00d1","teaching":{"steps":["Identify what the question tests: **countability**. Countable nouns name separate units and can be plural. Uncountable nouns name amounts or collections in the senses used here. Other senses may differ.","Stamps are used for separate countable units here. This classification applies to the stated sense.","Choose **A plural countable noun**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"**An adjective** gives the wrong word class, countability or number for the stated sense. Stamps are used for separate countable units here. This classification applies to the stated sense.","B":"Stamps are used for separate countable units here. This classification applies to the stated sense.","C":"**An uncountable noun** gives the wrong word class, countability or number for the stated sense. Stamps are used for separate countable units here. This classification applies to the stated sense.","D":"**A singular countable noun** gives the wrong word class, countability or number for the stated sense. Stamps are used for separate countable units here. This classification applies to the stated sense."}}},{"id":"dfdd32a8-2d3c-5605-a3b7-b3e301aed1df","topicSlug":"countable-uncountable","level":"A1","prompt":"While collecting postage stamps, ask about the quantity: How ____ stamps are there?","choices":[{"id":"A","text":"much"},{"id":"B","text":"a"},{"id":"C","text":"an"},{"id":"D","text":"many"}],"answerId":"D","hint":"Use how many before plural countable nouns and how much before uncountable nouns. Use plural agreement with the former and singular agreement with the latter. Focus on **quantity question** in this question.","explanation":"Use how many with plural countable stamps.","keywords":[],"source":"seed","skill":"quantity-question","contextKey":"quantity-1","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-countable-uncountable"],"version":"foundations-2026-09-v2","reviewStatus":"automated-checked; educator-review-pending"},"fingerprint":"0bc46569004c93aa75af1bd9cab23230c0ecb25314523cd83ef18567e32538a5","teaching":{"steps":["Identify what the question tests: **quantity question**. Use how many before plural countable nouns and how much before uncountable nouns. Use plural agreement with the former and singular agreement with the latter.","Use how many with plural countable stamps.","Choose **many**. Check the completed expression against the subject, time and intended meaning in the prompt."],"choiceReasons":{"A":"How **much** is used with uncountable nouns, but this noun has the other countability in the stated sense. Use how many with plural countable stamps.","B":"A/an mark one singular countable item; they do not make a how-much/how-many quantity question.","C":"A/an mark one singular countable item; they do not make a how-much/how-many quantity question.","D":"Use how many with plural countable stamps."}}},{"id"